#!/usr/bin/env python3
"""Boundary-induced sign flip in the inverse/direct-coupling kernel."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'research/benincasa/.tmp_sympy'));import sympy as s
src=json.loads((ROOT/'research/nima/results/nnmhv-kernel-wall-tail-boundary.json').read_text());K=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_matrix']]);K0=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_without_upper_boundary_transport']]);J=s.simplify(K.inv());J0=s.simplify(K0.inv());res=s.factor(K[1,0]*K[2,1]-K[1,1]*K[2,0]);formula=s.factor(res/(K[0,0]*K[1,1]*K[2,2]));sign=lambda A:[[int(s.sign(A[i,j])) for j in range(A.cols)] for i in range(A.rows)];checks={'inverse_long_range_entry_is_minor_over_diagonal_product':s.factor(J[2,0]-formula)==0,'unupdated_long_range_coupling_positive':s.sign(J0[2,0])==1,'updated_long_range_coupling_negative':s.sign(J[2,0])==-1,'nearest_neighbor_inverse_signs_remain_negative':s.sign(J[1,0])==s.sign(J[2,1])==s.sign(J0[1,0])==s.sign(J0[2,1])==-1,'diagonal_inverse_entries_remain_positive':all(s.sign(J[i,i])==s.sign(J0[i,i])==1 for i in range(3))}
out={'schema':'marici.nima.nnmhv-inverse-kernel-long-range-coupling.v1','inverse_without_boundary_signs':sign(J0),'inverse_with_boundary_signs':sign(J),'long_range_identity':'(K^-1)_(3,1) = [K_(2,1)K_(3,2)-K_(2,2)K_(3,1)]/[K_(1,1)K_(2,2)K_(3,3)]','long_range_without_boundary':str(s.factor(J0[2,0])),'long_range_with_boundary':str(s.factor(J[2,0])),'checks':{k:bool(v) for k,v in checks.items()},'passed':all(bool(v) for v in checks.values()),'meaning':'Kernel inversion removes mediated endpoint paths. Boundary transport leaves local inverse couplings unchanged in sign but reverses the direct longest-range coupling; the negative minor is exactly this inverse-coupling sign flip.','bridges':['Möbius/resolvent inversion','direct versus mediated interactions','precision-kernel sign structure','long-range frustration generated by a local diagonal update','Schur-complement effective coupling']};p=ROOT/'research/nima/results/nnmhv-inverse-kernel-long-range-coupling.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
